package com.smartserve.service;
import com.smartserve.entity.Category; import com.smartserve.entity.User; import com.smartserve.enums.Role; import com.smartserve.repository.CategoryRepository; import com.smartserve.repository.UserRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.List;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(CategoryRepository cats,UserRepository users,PasswordEncoder enc){return args->{ if(cats.count()==0){for(String n:List.of("Water Supply","Electricity","Road & Infrastructure","Sanitation","Garbage Collection","Public Transport","Street Lighting","Other"))cats.save(new Category(n,"Service category for "+n));} if(users.findByEmail("admin@smartserve.local").isEmpty()){User a=new User();a.setName("SmartServe Admin");a.setEmail("admin@smartserve.local");a.setPassword(enc.encode("Admin@123"));a.setRole(Role.ADMIN);users.save(a);} if(users.findByEmail("staff@smartserve.local").isEmpty()){User s=new User();s.setName("Support Agent");s.setEmail("staff@smartserve.local");s.setPassword(enc.encode("Staff@123"));s.setRole(Role.STAFF);users.save(s);} };} }
